import React, { useState } from 'react'
import { View, Text, TouchableOpacity } from 'react-native'
import { styles } from './styles'

export function Keyboard() {
    const [resultNumber, setResultNumber] = useState<string>('');

    function ButtonLimpar() {
        resultNumber !== '' ? setResultNumber(resultNumber.substring(0, resultNumber.length - 1)) : null
    }

    function ButtonAddNumber({ number }: { number: string }) {
        function LimiterResult() {
            if (resultNumber !== '' && number !== '0') {
                if (resultNumber.length < 4) {
                    setResultNumber(resultNumber + number);
                }
            }


        };

        return (
            <TouchableOpacity onPress={LimiterResult}>
                <Text style={styles.textNumber}>{number}</Text>
            </TouchableOpacity>
        );
    };

    return (
        <View style={styles.container} >

            <View style={styles.containerResultNumber}>
                <Text style={styles.textResultNumber}>{resultNumber ? (`0000${resultNumber}`).slice(-4) : '0000'}</Text>
            </View>

            <View style={styles.containerNumber}>
                <ButtonAddNumber number={'1'} />
                <ButtonAddNumber number={'2'} />
                <ButtonAddNumber number={'3'} />
            </View>

            <View style={{
                flexDirection: 'row',
                justifyContent: 'space-around',
                alignItems: 'center'
            }}>
                <ButtonAddNumber number={'4'} />
                <ButtonAddNumber number={'5'} />
                <ButtonAddNumber number={'6'} />
            </View>

            <View style={{
                flexDirection: 'row',
                justifyContent: 'space-around',
                alignItems: 'center'
            }}>
                <ButtonAddNumber number={'7'} />
                <ButtonAddNumber number={'8'} />
                <ButtonAddNumber number={'9'} />
            </View>

            <View style={styles.containerButton}>
                <TouchableOpacity onPress={() => ButtonLimpar()}>
                    <View style={styles.buttonLimpar}>
                        <Text style={styles.textButtonLimpar}>Limpar</Text>
                    </View>
                </TouchableOpacity>

                <ButtonAddNumber number={'0'} />

                <View style={styles.buttonConcluir}>
                    <Text style={styles.textButtonConcluir}>Concluir</Text>
                </View>
            </View>

        </View >
    );
};
